fields.InputDefinition:
{
  "goal": "Use the application switcher dropdown next to the logo (NOT the Ctrl+K search box) to open the Data Explorer app, then go to its Dashboards section (route /app/data-explorer/Dashboards). Click the 'New Dashboard' button, set the dashboard name to 'Regression Test Dashboard', and save it. The success state is the new dashboard created: it either opens directly after saving, or it appears as 'Regression Test Dashboard' in the dashboards list/card view. Pages and save operations can take 10-30s in this resource-constrained environment - wait for the save to complete, do not navigate away early.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 45,
  "judgeValidationCriteria": [
    "A new dashboard creation flow was completed with the name 'Regression Test Dashboard' entered",
    "After saving, the dashboard named 'Regression Test Dashboard' is shown - either opened in its own view/tab or listed in the Dashboards browser",
    "No error messages, blank screens, or crash pages"
  ]
}
